MATCH (s:Service {id: $sid})-[:REQUIRES]->(r:Requirement)
WHERE r.group = false AND NOT EXISTS {
MATCH (r)-[:APPLIES_WHEN]->(v:Variant)
WHERE EXISTS { MATCH (x:Variant) WHERE x.id IN $variant_ids AND x.dimension = v.dimension }
AND NOT EXISTS { MATCH (r)-[:APPLIES_WHEN]->(w:Variant) WHERE w.id IN $variant_ids AND w.dimension = v.dimension }
}
RETURN count(r) AS n
LIMIT 1

MATCH (s:Service {id: $sid})-[:HAS_STEP]->(st:Step)-[:CHARGES]->(f:Fee)
WHERE NOT EXISTS {
MATCH (f)-[:APPLIES_WHEN]->(v:Variant)
WHERE EXISTS { MATCH (x:Variant) WHERE x.id IN $variant_ids AND x.dimension = v.dimension }
AND NOT EXISTS { MATCH (f)-[:APPLIES_WHEN]->(w:Variant) WHERE w.id IN $variant_ids AND w.dimension = v.dimension }
}
RETURN st.id, st.order, st.citizen_action, f.id, f.label, f.amount_min, f.amount_max, f.unit, f.note, f.condition_text
ORDER BY st.order, f.id
LIMIT 50

MATCH (s:Service {id: $sid})-[:REQUIRES]->(r:Requirement)
WHERE NOT EXISTS {
MATCH (r)-[:APPLIES_WHEN]->(v:Variant)
WHERE EXISTS { MATCH (x:Variant) WHERE x.id IN $variant_ids AND x.dimension = v.dimension }
AND NOT EXISTS { MATCH (r)-[:APPLIES_WHEN]->(w:Variant) WHERE w.id IN $variant_ids AND w.dimension = v.dimension }
}
OPTIONAL MATCH (r)-[:SATISFIED_BY]->(d:Service)<-[:OFFERS]-(o1:Office)
